// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.benchmark;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import org.apache.commons.io.FileUtils;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.benchmark.FoafCliqueQueryCatalog.QueryScenario;
import org.eclipse.rdf4j.sail.lmdb.evaluation.JoinDispatchTestAccess;
import org.eclipse.rdf4j.sail.lmdb.evaluation.KernelExecutionTestAccess;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;

/**
 * Dispatch census over the FOAF-clique catalog (ExecPlan .agent/lmdb-join-strategy-execplan.md, Milestone 1 pre-step):
 * for each catalog query, executed under the native engine, record which operator rungs engaged — Leapfrog Triejoin
 * (WCOJ), the Janino aggregate kernel, the Janino pipeline, and the IR kernel — via their telemetry counters. The
 * census output is printed to stdout (captured in the Surefire report) as a table of per-query counter deltas, so
 * Milestone 1 can pick its primary workload from queries that actually reach the leapfrog operator.
 *
 * This is a census harness, not a behavior contract: it asserts only that every catalog query executes and produces
 * rows under the native engine. Counter expectations deliberately stay unasserted so the census keeps working as
 * dispatch evolves.
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class FoafCliqueDispatchCensusTest {

	private static final int PEOPLE_COUNT = 300;
	private static final int CLIQUE_PERCENTAGE = 30;
	private static final int MIN_CLIQUE_SIZE = 3;
	private static final int MAX_CLIQUE_SIZE = 6;
	private static final int RANDOM_KNOWS_EDGES = 900;
	private static final long SEED = 12345L;

	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String WCOJ_FLAG = "rdf4j.lmdb.wcoj.enabled";

	private Path tempDir;
	private SailRepository repository;
	private String previousNative;
	private String previousWcoj;

	@BeforeAll
	void setUp() throws IOException {
		previousNative = System.getProperty(NATIVE_FLAG);
		previousWcoj = System.getProperty(WCOJ_FLAG);
		FoafCliqueQueryBenchmark.applyEngineMode(FoafCliqueQueryBenchmark.MODE_NATIVE);
		tempDir = Files.createTempDirectory("rdf4j-lmdb-foaf-clique-census");
		repository = FoafCliqueQueryBenchmark.createRepository(tempDir.toFile());
		repository.init();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			new FoafCliqueDataGenerator(PEOPLE_COUNT, CLIQUE_PERCENTAGE, MIN_CLIQUE_SIZE, MAX_CLIQUE_SIZE,
					RANDOM_KNOWS_EDGES, SEED).populate(connection);
		}
	}

	@AfterAll
	void tearDown() throws IOException {
		if (repository != null) {
			repository.shutDown();
		}
		if (tempDir != null) {
			FileUtils.deleteDirectory(tempDir.toFile());
		}
		restore(NATIVE_FLAG, previousNative);
		restore(WCOJ_FLAG, previousWcoj);
	}

	private static void restore(String key, String previous) {
		if (previous == null) {
			System.clearProperty(key);
		} else {
			System.setProperty(key, previous);
		}
	}

	@Test
	void censusOfOperatorDispatchPerCatalogQuery() {
		System.out.printf("%n%-40s %8s %6s %6s %6s %6s %6s %6s %6s%n",
				"scenario", "rows", "lfPln", "lfOpn", "lfPar", "jaPln", "jaOpn", "jaDcl", "irOpn");
		for (QueryScenario scenario : FoafCliqueQueryCatalog.allScenarios()) {
			// Warm once so per-plan one-time work (compilation, caches) does not skew the counted run.
			executeAndCount(scenario.query());

			long lfPlanned = JoinDispatchTestAccess.leapfrogPlanned();
			long lfOpened = JoinDispatchTestAccess.leapfrogOpened();
			long lfParallel = JoinDispatchTestAccess.leapfrogParallelRuns();
			long jaPlanned = JoinDispatchTestAccess.janinoAggregatePlanned();
			long jaOpened = JoinDispatchTestAccess.janinoAggregateOpened();
			long jaDeclined = JoinDispatchTestAccess.janinoAggregateDeclined();
			long irOpened = KernelExecutionTestAccess.opened() + KernelExecutionTestAccess.aggOpened();

			long rows = executeAndCount(scenario.query());

			System.out.printf("%-40s %8d %6d %6d %6d %6d %6d %6d %6d%n",
					scenario.benchmarkMethodName(), rows,
					JoinDispatchTestAccess.leapfrogPlanned() - lfPlanned,
					JoinDispatchTestAccess.leapfrogOpened() - lfOpened,
					JoinDispatchTestAccess.leapfrogParallelRuns() - lfParallel,
					JoinDispatchTestAccess.janinoAggregatePlanned() - jaPlanned,
					JoinDispatchTestAccess.janinoAggregateOpened() - jaOpened,
					JoinDispatchTestAccess.janinoAggregateDeclined() - jaDeclined,
					KernelExecutionTestAccess.opened() + KernelExecutionTestAccess.aggOpened() - irOpened);

			assertTrue(rows > 0, scenario.benchmarkMethodName() + " must produce rows under the native engine");
		}
	}

	private long executeAndCount(String query) {
		long rows = 0;
		try (RepositoryConnection connection = repository.getConnection()) {
			try (var result = connection.prepareTupleQuery(query).evaluate()) {
				while (result.hasNext()) {
					result.next();
					rows++;
				}
			}
		}
		return rows;
	}
}
